/* No grid gap: the error row and the file list carry their own spacing, so each can open from a true zero height. */
.wrapper { position: relative; display: grid; min-width: 0; color: var(--foreground); }
.dropzone { position: relative; display: grid; min-width: 0; border-radius: var(--radius-surface); background: var(--surface); transition: background-color var(--duration-standard) var(--ease-standard), border-radius var(--duration-spring) var(--ease-spring); }
/* A folded prompt is a slimmer surface, so its corners step down to the panel radius. */
.dropzone.compact { border-radius: var(--radius-panel); }
/* The edge is a drawn stroke, fitted to the perimeter in script, so a drag can close its dashes into one line. */
.edge { position: absolute; top: .5px; left: .5px; width: calc(100% - 1px); height: calc(100% - 1px); overflow: visible; pointer-events: none; }
.edge rect { fill: none; stroke: var(--border-strong); stroke-width: 1; stroke-dasharray: 3.5 3.5; stroke-dashoffset: 0; transition: stroke var(--duration-fast) var(--ease-standard), stroke-dasharray var(--duration-standard) var(--ease-standard), stroke-dashoffset var(--duration-standard) var(--ease-standard); }
.trigger { display: flex; width: 100%; flex-direction: column; align-items: stretch; justify-content: center; border: 0; border-radius: inherit; padding: 34px var(--space-5); background: transparent; color: inherit; font: inherit; letter-spacing: var(--tracking-body); text-align: center; cursor: pointer; }
.trigger > * { pointer-events: none; }
@media (hover: hover) and (pointer: fine) {
  .dropzone:has(.trigger:hover) { background: var(--surface-muted); }
  .dropzone:has(.trigger:hover) .edge rect { stroke: var(--text-muted); }
}
/* Color is the only press response: the target never scales. */
.dropzone:has(.trigger:active) { background: var(--surface-muted); }
/* A file over the target closes the dashes into a solid edge and the target breathes, slowly, while it waits. */
.dropzone.dragging { background: color-mix(in oklch, var(--accent) 2.5%, var(--surface)); animation: breathe 2.2s cubic-bezier(.45, 0, .55, 1) infinite; }
@keyframes breathe { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.012); } }
/* Light that follows the pointer: a wash inside, and a brighter stretch of the edge nearest the file. */
.wash, .glow { position: absolute; inset: 0; border-radius: inherit; opacity: 0; pointer-events: none; transition: opacity var(--duration-standard) var(--ease-standard); }
.glow { padding: 1.5px; -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); }
.dragging .wash, .dragging .glow { opacity: 1; }
.dragging .edge rect { stroke: color-mix(in oklch, var(--accent) 40%, var(--border)); stroke-dasharray: 7 0; stroke-dashoffset: 1.75; }
/* No gaps between the prompt's parts: each slot carries its own space, so a folding slot takes its space with it. */
.iconSlot, .noteSlot { display: flex; flex-direction: column; overflow: hidden; }
/* Three sheets of paper, the target's one illustration. The slot's top margin is room for them to lift without clipping. */
.sheets { position: relative; display: block; width: 36px; height: 44px; align-self: center; margin: 10px 0 14px; }
.sheet {
  --r: 0deg; --x: 0px; --y: 0px;
  position: absolute; inset: 0; display: grid; place-items: end center; padding: 0 0 5px;
  border: 1px solid var(--border); border-radius: 7px; background: var(--surface-raised); color: var(--text-muted);
  box-shadow: 0 1px 2px oklch(0% 0 0 / .05), 0 3px 8px oklch(0% 0 0 / .04);
  transform: translate(var(--x), var(--y)) rotate(var(--r));
  transform-origin: 50% 100%;
  transition: transform 420ms cubic-bezier(.34, 1.3, .64, 1), color var(--duration-standard) var(--ease-standard), border-color var(--duration-standard) var(--ease-standard);
}
.sheet::before, .sheet::after { position: absolute; top: 8px; left: 7px; width: 16px; height: 2px; border-radius: 2px; background: currentColor; content: ""; opacity: .3; }
.sheet::after { top: 13px; width: 11px; }
.sheet > svg { transition: transform 420ms cubic-bezier(.34, 1.3, .64, 1); }
.dragging .sheet > svg { transform: translateY(-3px); }
.sheet[data-sheet="back"] { --r: -10deg; --x: -9px; --y: 2px; }
.sheet[data-sheet="side"] { --r: 10deg; --x: 9px; --y: 2px; }
@media (hover: hover) and (pointer: fine) {
  .dropzone:has(.trigger:hover) .sheet[data-sheet="back"] { --r: -15deg; --x: -13px; }
  .dropzone:has(.trigger:hover) .sheet[data-sheet="side"] { --r: 15deg; --x: 13px; }
  .dropzone:has(.trigger:hover) .sheet[data-sheet="front"] { --y: -2px; }
}
.dragging .sheet { color: var(--text-secondary); border-color: var(--border-strong); }
.dropzone.dragging .sheet[data-sheet="back"] { --r: -22deg; --x: -20px; --y: -2px; }
.dropzone.dragging .sheet[data-sheet="side"] { --r: 22deg; --x: 20px; --y: -2px; }
.dropzone.dragging .sheet[data-sheet="front"] { --y: -8px; }
/* Full width and centered text: the label box never moves, so an outgoing label leaves from exactly where it was. */
.label { position: relative; display: block; font-size: var(--text-sm); font-weight: 500; line-height: var(--leading-body); }
.labelText { display: inline-block; max-width: 100%; overflow: hidden; text-overflow: ellipsis; vertical-align: top; white-space: nowrap; }
.hint { margin-top: 6px; color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); }
.note { padding-top: 6px; color: var(--text-muted); font-size: var(--text-xs); line-height: var(--leading-body); }
.input { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }
.messageSlot { overflow: hidden; }
.error { display: flex; align-items: flex-start; gap: 6px; padding-top: var(--space-3); color: var(--danger); font-size: var(--text-sm); line-height: var(--leading-body); }
/* The icon sits on the first line's optical center, so a wrapped message keeps it at the top. */
.errorIcon { flex: 0 0 auto; margin-top: 3px; }
.errorCopy { position: relative; min-width: 0; flex: 1; }

.list { display: grid; min-width: 0; margin: 0; padding: 0; list-style: none; container: dropzone-list / inline-size; }
.inside .list { padding-inline: 12px; }
/* Rows animate height; the gap lives inside the clipped row as margin, so a closing row reaches a true zero. */
.item { min-width: 0; overflow: hidden; }
.row { position: relative; display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; align-items: center; column-gap: 12px; min-height: 58px; margin-top: 8px; border: 1px solid var(--border); border-radius: var(--radius-control); padding: 8px 8px 8px 9px; background: var(--surface); transition: border-color var(--duration-standard) var(--ease-standard); }
.row.isFailed { border-color: color-mix(in oklch, var(--danger) 26%, var(--border)); }
.fileIcon { display: grid; width: 40px; height: 40px; place-items: center; color: var(--text-secondary); }
.thumb { display: block; width: 40px; height: 40px; overflow: hidden; border-radius: 10px; background: var(--surface-muted); box-shadow: inset 0 0 0 1px oklch(0% 0 0 / .06); }
.thumb img { display: block; width: 100%; height: 100%; object-fit: cover; }
.copy { display: grid; min-width: 0; }
.name { overflow: hidden; font-size: var(--text-sm); font-weight: 500; line-height: var(--leading-body); text-overflow: ellipsis; white-space: nowrap; }
.meta { display: flex; min-width: 0; align-items: center; margin-top: 1px; color: var(--text-muted); font-size: var(--text-xs); line-height: var(--leading-body); font-variant-numeric: tabular-nums; white-space: nowrap; }
.dot { padding-inline: 6px; }
/* The outgoing status is measured against this box when it pops out to leave. */
.phase { position: relative; display: flex; min-width: 0; flex: 1; }
.state { display: inline-flex; min-width: 0; align-items: center; gap: 5px; }
.uploaded { color: var(--text-secondary); }
.uploaded .stateIcon { color: var(--success); }
.failed { color: var(--danger); }
.stateIcon { flex: 0 0 auto; }
.reason { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.percent { font-variant-numeric: tabular-nums; }
.barFrame { display: block; overflow: hidden; }
.bar { display: block; height: 4px; margin: 7px 0 2px; overflow: hidden; border-radius: var(--radius-pill); background: var(--border); }
/* The fill slides in from the left instead of scaling, so its rounded end keeps its shape at every value. */
.barFill { display: block; width: 100%; height: 100%; border-radius: inherit; background: var(--accent); }
.actions { display: flex; align-items: center; }
.retrySlot { display: flex; overflow: hidden; }
.retryInner { display: flex; padding: 3px 6px 3px 3px; }
.retry, .remove { display: grid; place-items: center; border: 0; color: var(--text-secondary); font: inherit; cursor: pointer; transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }
.retry { display: flex; height: 30px; align-items: center; gap: 5px; border: 1px solid var(--border); border-radius: var(--radius-pill); padding: 0 12px 0 10px; background: var(--surface); color: var(--foreground); font-size: var(--text-xs); font-weight: 500; letter-spacing: var(--tracking-body); white-space: nowrap; }
/* On narrow lists Retry keeps only its icon, so the failure reason keeps the room to be read in full. */
@container dropzone-list (max-width: 440px) { .retry { width: 30px; justify-content: center; padding: 0; } .retryLabel { display: none; } }
/* On the narrowest lists the type icon steps aside for the name and status. */
@container dropzone-list (max-width: 300px) { .row { grid-template-columns: minmax(0, 1fr) auto; padding-left: 14px; } .fileIcon, .thumb { display: none; } }
.remove { width: 32px; height: 32px; border-radius: var(--radius-pill); background: transparent; }
@media (hover: hover) and (pointer: fine) {
  .retry:hover { border-color: var(--border-strong); background: var(--surface-muted); }
  .remove:hover { background: var(--surface-muted); color: var(--foreground); }
}
/* Quick press, spring release. Neither button anchors a floating layer. */
.retry:active, .remove:active { transform: scale(.97); transition-duration: var(--duration-instant); transition-timing-function: var(--ease-standard); }
/* Words are measured against this box when they pop out to leave, so it must be the positioned parent. */
.words { position: relative; display: block; }
.word { display: inline-block; white-space: pre; }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@media (prefers-reduced-motion: reduce) {
  .dropzone, .edge rect, .sheet, .row, .retry, .remove, .wash, .glow { transition: none; }
  .dropzone.dragging { animation: none; }
  .retry:active, .remove:active { transform: none; }
}
.dropzone:has(.trigger:focus-visible) { box-shadow: 0 0 0 3px var(--focus-ring); }
.retry:focus-visible, .remove:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--focus-ring); }
